\section{Introduction}

\subsection{Background}

The Poisson summation formula occupies an unusual position in analysis: it is simultaneously a computational device, a structural statement about duality, and a bridge between arithmetic and harmonic analysis. Classically, for suitable $f : \mathbb{R}^n \to \mathbb{C}$ and a lattice $\Lambda \subseteq \mathbb{R}^n$ with dual lattice $\Lambda^{*}$,
\[
\sum_{\lambda \in \Lambda} f(\lambda) \;=\; \frac{1}{\operatorname{covol}(\Lambda)} \sum_{\mu \in \Lambda^{*}} \hat{f}(\mu).
\]
It underwrites the sampling theorem, the functional equation of the Jacobi theta function, Ewald summation, and lattice-point counting.

The formula is habitually presented as a \emph{tool}: one is handed a lattice and told what the identity yields. But its statement makes formal sense in far greater generality than its proof requires. In the finite abelian setting --- where every difficulty of convergence and decay disappears and only the algebra remains --- one may write the identity down for an arbitrary subset. The question of which subsets satisfy it is well posed and elementary to state. This paper settles it, in the strongest form we could formulate.

\subsection{Setting and notation}

Throughout, $G$ is a finite abelian group, written additively.

A \emph{character} of $G$ is a homomorphism $\psi : G \to \mathbb{C}^{\times}$; since $G$ is finite, $|\psi(x)| = 1$ and $\overline{\psi(x)} = \psi(-x) = \psi(x)^{-1}$. The characters form a group $\widehat{G}$ with $|\widehat{G}| = |G|$. The Fourier transform of $f : G \to \mathbb{C}$ is
\[
\hat{f}(\psi) \;=\; \sum_{x \in G} \overline{\psi(x)}\, f(x), \qquad \psi \in \widehat{G}.
\]
We write $\delta_y$ for the Dirac delta at $y$, so $\widehat{\delta_y}(\psi) = \overline{\psi(y)}$. For an arbitrary subset $S \subseteq G$ the \emph{annihilator} is
\[
S^{\perp} \;=\; \{\psi \in \widehat{G} : \psi(x) = 1 \text{ for all } x \in S\},
\]
always a subgroup of $\widehat{G}$ whether or not $S$ is a subgroup. We write $\gen{S}$ for the smallest subgroup of $G$ containing $S$, $\supp(f) = \{x : f(x) \ne 0\}$, and $\mathbf{1}_S$ for the indicator of $S$.

\subsection{The classical direction}

\begin{theorem}[Poisson summation for subgroups]\label{thm:classical}
Let $H \le G$ be a subgroup. Then for every $f : G \to \mathbb{C}$,
\[
|G| \sum_{x \in H} f(x) \;=\; |H| \sum_{\psi \in H^{\perp}} \hat{f}(\psi).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Expand the right-hand side and interchange summation:
\[
|H| \sum_{\psi \in H^{\perp}} \hat{f}(\psi) = |H| \sum_{y \in G} f(y) \sum_{\psi \in H^{\perp}} \overline{\psi(y)} .
\]
The inner sum is a character sum over the subgroup $H^{\perp} \le \widehat{G}$; by orthogonality it equals $|H^{\perp}|$ when $y$ is annihilated by every element of $H^{\perp}$, that is when $y \in H$ by the double-annihilator theorem, and $0$ otherwise. Since $|H| \cdot |H^{\perp}| = |G|$, the right-hand side becomes $|G| \sum_{y \in H} f(y)$.
\end{proof}

We record the accompanying size identity, generalised in Section~\ref{sec:annih}:
\begin{equation}\label{eq:sizesubgroup}
|H| \cdot |H^{\perp}| = |G| \qquad \text{for every subgroup } H \le G.
\end{equation}

\subsection{The question, and the answer}

\begin{definition}[Poisson set]\label{def:poisson}
A subset $S \subseteq G$ is a \emph{Poisson set} if
\begin{equation}\label{eq:PS}\tag{$P_S$}
|G| \sum_{x \in S} f(x) \;=\; |S| \sum_{\psi \in S^{\perp}} \hat{f}(\psi) \qquad \text{for all } f : G \to \mathbb{C}.
\end{equation}
\end{definition}

Theorem~\ref{thm:classical} says subgroups are Poisson sets. The empty set is trivially one: both sides vanish. Our main results say these are all, and quantify the failure otherwise.

\begin{theoremA}[Classification]
A subset $S \subseteq G$ is a Poisson set if and only if $S = \emptyset$ or $S$ is a subgroup of $G$.
\end{theoremA}

\begin{theoremB}[One-test-function rigidity]
Let $S \subseteq G$ and $y_0 \in S$. If \eqref{eq:PS} holds for the single function $f = \delta_{y_0}$, then $S = \gen{S}$; in particular $S$ is a subgroup.
\end{theoremB}

\begin{theoremC}[Exact defect formula]
For $S \subseteq G$ and $f : G \to \mathbb{C}$ define the \emph{Poisson defect}
\[
D_S(f) \;=\; |G| \sum_{x \in S} f(x) \;-\; |S| \sum_{\psi \in S^{\perp}} \hat{f}(\psi).
\]
Then
\[
|\gen{S}| \cdot D_S(f) \;=\; |G| \Big( |\gen{S}| \sum_{x \in S} f(x) \;-\; |S| \sum_{x \in \gen{S}} f(x) \Big).
\]
\end{theoremC}

\begin{theoremD}[Gap theorem]
If $S$ is nonempty and $S \ne \gen{S}$, then there exists $y_0 \in S$ with
\[
\big| D_S(\delta_{y_0}) \big| \;\ge\; |\gen{S}| - |S| \;\ge\; 1 .
\]
\end{theoremD}

Theorem D is the precise sense in which no approximate theory exists: the defect functional does not take small nonzero values on Dirac data. Theorem B is the sense in which the identity is rigid on contact: the weakest possible test function already forces the full structural conclusion.

\section{Annihilators of arbitrary sets}\label{sec:annih}

The whole argument rests on one asymmetry: the left-hand side of \eqref{eq:PS} sees $S$ exactly, while the right-hand side sees only $S^{\perp}$ --- and $S^{\perp}$ cannot distinguish $S$ from the subgroup it generates.

\begin{lemma}[Blindness of the annihilator]\label{lem:blind}
For every subset $S \subseteq G$ we have $S^{\perp} = \gen{S}^{\perp}$.
\end{lemma}

\begin{proof}
The inclusion $\gen{S}^{\perp} \subseteq S^{\perp}$ is immediate from $S \subseteq \gen{S}$. Conversely, fix $\psi \in S^{\perp}$ and set $K = \ker \psi = \{y \in G : \psi(y) = 1\}$. Since $\psi$ is a homomorphism, $K$ is a subgroup: $\psi(0) = 1$; if $\psi(a) = \psi(b) = 1$ then $\psi(a+b) = \psi(a)\psi(b) = 1$; and $\psi(-a) = \psi(a)^{-1} = 1$. By hypothesis $S \subseteq K$, and $\gen{S}$ is the smallest subgroup containing $S$, so $\gen{S} \subseteq K$, i.e.\ $\psi \in \gen{S}^{\perp}$.
\end{proof}

The proof is three lines, but it is the entire mechanism; everything downstream is bookkeeping around it.

\begin{corollary}\label{cor:size}
For every subset $S \subseteq G$ we have $|\gen{S}| \cdot |S^{\perp}| = |G|$.
\end{corollary}

\begin{proof}
Combine Lemma~\ref{lem:blind} with \eqref{eq:sizesubgroup} applied to $H = \gen{S}$.
\end{proof}

Corollary~\ref{cor:size} already explains why \eqref{eq:PS} is so constrained. The right-hand side is structurally a formula about $\gen{S}$; the coefficient $|S|$ is the only place where $S$ itself enters. If $S \subsetneq \gen{S}$, the coefficient is wrong and there is nothing to compensate.

\section{The fundamental character sum}

\begin{proposition}\label{prop:charsum}
For every subset $S \subseteq G$ and every $y \in G$,
\[
|\gen{S}| \sum_{\psi \in S^{\perp}} \overline{\psi(y)} \;=\;
\begin{cases} |G| & \text{if } y \in \gen{S},\\ 0 & \text{otherwise.}\end{cases}
\]
\end{proposition}

\begin{proof}
Apply Theorem~\ref{thm:classical} to $H = \gen{S}$ and $f = \delta_y$. The left-hand side is $|G| \cdot \mathbf{1}[y \in \gen{S}]$; the right-hand side is $|\gen{S}| \sum_{\psi \in \gen{S}^{\perp}} \overline{\psi(y)}$, and $\gen{S}^{\perp} = S^{\perp}$ by Lemma~\ref{lem:blind}.
\end{proof}

Proposition~\ref{prop:charsum} is the analytic content of the paper compressed into one display: the annihilator character sum is a sharp indicator of membership in $\gen{S}$, with no reference to $S$ beyond the subgroup it generates.

\section{The converse}

\subsection{One test function suffices}

\begin{proof}[Proof of Theorem B]
Since $y_0 \in S$, the left-hand side of \eqref{eq:PS} at $f = \delta_{y_0}$ equals $|G|$. Since $y_0 \in \gen{S}$, Proposition~\ref{prop:charsum} gives $|\gen{S}| \sum_{\psi \in S^{\perp}} \overline{\psi(y_0)} = |G|$. Multiplying the hypothesis by $|\gen{S}|$ and using $\widehat{\delta_{y_0}}(\psi) = \overline{\psi(y_0)}$,
\[
|\gen{S}| \cdot |G| \;=\; |S| \Big( |\gen{S}| \sum_{\psi \in S^{\perp}} \overline{\psi(y_0)} \Big) \;=\; |S| \cdot |G| .
\]
As $|G| \ne 0$ we obtain $|\gen{S}| = |S|$; since $S \subseteq \gen{S}$ and both are finite of equal size, $S = \gen{S}$.
\end{proof}

Note what the proof does \emph{not} use: no orthogonality beyond Theorem~\ref{thm:classical}, no structure theorem, and no property of $S$ other than nonemptiness.

\subsection{Classification}

\begin{theorem}\label{thm:equiv}
For nonempty $S \subseteq G$ the following are equivalent:
\begin{enumerate}
\item $S$ is a Poisson set;
\item \eqref{eq:PS} holds for $f = \delta_{y_0}$ for some $y_0 \in S$;
\item $S$ is a subgroup of $G$;
\item $0 \in S$ and $x - y \in S$ whenever $x, y \in S$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) $\Rightarrow$ (2) is trivial. (2) $\Rightarrow$ (3) is Theorem B, since $\gen{S}$ is a subgroup. (3) $\Rightarrow$ (1) is Theorem~\ref{thm:classical}. (3) $\Leftrightarrow$ (4) is the subgroup criterion: from $0 \in S$ and closure under subtraction, $-y = 0 - y \in S$ and $x + y = x - (-y) \in S$.
\end{proof}

\begin{proof}[Proof of Theorem A]
If $S = \emptyset$ both sides of \eqref{eq:PS} vanish, since the sum over $\emptyset$ is $0$ and $|S| = 0$. If $S \ne \emptyset$, apply Theorem~\ref{thm:equiv}. Conversely subgroups are Poisson sets by Theorem~\ref{thm:classical}.
\end{proof}

The empty set is a genuine exception rather than a degenerate subgroup, since every subgroup contains $0$; so the nonemptiness hypothesis in Theorem~\ref{thm:equiv} is sharp.

\begin{corollary}[Decidability]\label{cor:dec}
For any finite abelian $G$ and any $S \subseteq G$, the analytic property \eqref{eq:PS} --- quantified over the $|G|$-dimensional space of test functions --- is equivalent to the finite combinatorial condition
\[
S = \emptyset \quad\text{or}\quad \big( 0 \in S \ \text{ and } \ \forall x, y \in S:\; x - y \in S \big),
\]
checkable in $O(|S|^2)$ group operations.
\end{corollary}

\subsection{The defect formula}

\begin{proof}[Proof of Theorem C]
By Theorem~\ref{thm:classical} applied to $H = \gen{S}$ and Lemma~\ref{lem:blind},
\[
|\gen{S}| \sum_{\psi \in S^{\perp}} \hat{f}(\psi) \;=\; |\gen{S}| \sum_{\psi \in \gen{S}^{\perp}} \hat{f}(\psi) \;=\; |G| \sum_{x \in \gen{S}} f(x).
\]
Multiplying by $|S|$, substituting into $|\gen{S}| D_S(f) = |\gen{S}| \big(|G| \sum_S f - |S| \sum_{S^{\perp}} \hat f\big)$, and simplifying gives the identity.
\end{proof}

Dividing through by $|G|\cdot|S|\cdot|\gen{S}|$ yields the interpretation
\[
\frac{D_S(f)}{|G| \cdot |S|} \;=\; \frac{1}{|S|}\sum_{x \in S} f(x) \;-\; \frac{1}{|\gen{S}|}\sum_{x \in \gen{S}} f(x):
\]
the normalised defect is exactly the difference between the mean of $f$ over $S$ and over $\gen{S}$. Equivalently, $f \mapsto D_S(f)$ is, up to the factor $|G|\,|S|$, integration against the signed measure
\[
\mu_S \;=\; \tfrac{1}{|S|} \mathbf{1}_S - \tfrac{1}{|\gen{S}|} \mathbf{1}_{\gen{S}},
\]
supported on $\gen{S}$, of total mass $0$ and total variation $2\big(1 - |S|/|\gen{S}|\big)$.

\section{Quantitative rigidity}

\begin{proof}[Proof of Theorem D]
Pick any $y_0 \in S$; then $y_0 \in \gen{S}$ as well, and both $\sum_{x \in S}\delta_{y_0}(x)$ and $\sum_{x \in \gen{S}}\delta_{y_0}(x)$ equal $1$. Theorem C gives
\[
|\gen{S}| \cdot D_S(\delta_{y_0}) \;=\; |G| \big( |\gen{S}| - |S| \big),
\]
a nonnegative real quantity with $|\gen{S}| - |S| \ge 1$ since the containment $S \subseteq \gen{S}$ is strict. Taking absolute values and using $|G|/|\gen{S}| \ge 1$,
\[
\big| D_S(\delta_{y_0}) \big| \;=\; \frac{|G|}{|\gen{S}|}\big(|\gen{S}| - |S|\big) \;\ge\; |\gen{S}| - |S|. \qedhere
\]
\end{proof}

The proof gives an exact value: for every $y_0 \in S$,
\begin{equation}\label{eq:exactdefect}
D_S(\delta_{y_0}) \;=\; [G : \gen{S}] \cdot \big( |\gen{S}| - |S| \big),
\end{equation}
where $[G:\gen{S}] = |G|/|\gen{S}| = |S^{\perp}|$. The defect at a delta inside $S$ is a positive integer independent of the chosen point, factoring as (index of the generated subgroup) $\times$ (number of missing points).

\begin{corollary}[No approximate Poisson sets]\label{cor:gap}
For any $\varepsilon < 1$ there is no nonempty non-subgroup $S \subseteq G$ with $|D_S(f)| \le \varepsilon$ for all $f$ with $\|f\|_{\infty} \le 1$. The defect functional has a gap of size $1$ at zero.
\end{corollary}

\begin{theorem}[Rigidity of the normalising constant]\label{thm:constant}
Let $S \subseteq G$ be nonempty and suppose there is $c \in \mathbb{C}$ with
\[
|G| \sum_{x \in S} f(x) \;=\; c \sum_{\psi \in S^{\perp}} \hat{f}(\psi) \qquad \text{for all } f : G \to \mathbb{C}.
\]
Then $S$ is a subgroup and $c = |S|$.
\end{theorem}

\begin{proof}[Proof sketch]
\emph{Step 1.} Take $f = \delta_{y_0}$ with $y_0 \in S$: the left side is $|G|$; multiplying by $|\gen{S}|$ and applying Proposition~\ref{prop:charsum} at $y_0 \in \gen{S}$ turns the right side into $c\,|G|$. Hence $c = |\gen{S}|$.

\emph{Step 2.} Suppose $y \in \gen{S} \setminus S$ and take $f = \delta_y$: the left side vanishes, while the same manipulation turns the right side into $c\,|G| = |\gen{S}|\,|G| \ne 0$, a contradiction. Hence $\gen{S} \subseteq S$, so $S = \gen{S}$ and $c = |S|$.
\end{proof}

Thus the constant $|H|$ in Theorem~\ref{thm:classical} is not a normalisation convention: it is the unique constant for which any such identity can hold, and its correctness is equivalent to the subgroup property.

\section{The affine theory: Poisson summation characterises cosets}

\begin{lemma}[Translation phase]\label{lem:phase}
For $f : G \to \mathbb{C}$, $x_0 \in G$ and $\psi \in \widehat{G}$, $\;\widehat{f(x_0 + \cdot)}(\psi) = \psi(x_0)\, \hat{f}(\psi)$.
\end{lemma}

\begin{proof}
Substituting $z = x_0 + y$ and using $\overline{\psi(z - x_0)} = \overline{\psi(z)}\,\psi(x_0)$,
\[
\sum_{y} \overline{\psi(y)} f(x_0 + y) = \sum_z \overline{\psi(z - x_0)} f(z) = \psi(x_0) \sum_z \overline{\psi(z)} f(z). \qedhere
\]
\end{proof}

\begin{definition}
For $S \subseteq G$ and a base point $x_0 \in G$, say $S$ is an \emph{affine Poisson set with base point $x_0$} if
\begin{equation}\label{eq:PSx}\tag{$P_{S,x_0}$}
|G| \sum_{x \in S} f(x) \;=\; |S| \sum_{\psi \in (S - x_0)^{\perp}} \psi(x_0)\, \hat{f}(\psi) \qquad \text{for all } f.
\end{equation}
\end{definition}

\begin{theorem}\label{thm:translate}
\eqref{eq:PSx} holds for $S$ if and only if \eqref{eq:PS} holds for the translate $T = S - x_0$.
\end{theorem}

\begin{proof}[Proof sketch]
The substitution $f \mapsto f(x_0 + \cdot)$ maps $\sum_{y \in T} f(x_0 + y)$ to $\sum_{x \in S} f(x)$ and, by Lemma~\ref{lem:phase}, converts $\hat{f}(\psi)$ into $\psi(x_0)\hat{f}(\psi)$; the cardinalities agree since translation is a bijection. The two identities are each other's images under this invertible substitution.
\end{proof}

\begin{theorem}[Coset characterisation]\label{thm:coset}
Let $x_0 \in S$. Then \eqref{eq:PSx} holds if and only if $S = x_0 + H$ for some subgroup $H \le G$, i.e.\ iff $S$ is a coset.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:translate}, \eqref{eq:PSx} is \eqref{eq:PS} for $S - x_0$, which contains $0$ and so is nonempty. Theorem~\ref{thm:equiv} then says this holds iff $S - x_0$ is a subgroup $H$, i.e.\ iff $S = x_0 + H$.
\end{proof}

\begin{corollary}
A set $S$ admits \emph{some} base point in $S$ for which the affine identity holds iff $S$ is a coset of a subgroup.
\end{corollary}

\begin{example}
The squares modulo $8$, $S = \{0,1,4\}$, form neither a subgroup nor a coset: were $S = x_0 + H$, then $H = S - x_0$ would be closed under subtraction, but for every $x_0 \in S$ one of $1 - 4 + x_0$, $4 - 1 + x_0$ escapes $S$. Hence no base point rescues Poisson summation for the quadratic residues mod $8$.
\end{example}

\section{Poisson sets are the uncertainty extremals}

\begin{proposition}[Lower estimate]\label{prop:lower}
For every $S \subseteq G$, $\;|S| \cdot |S^{\perp}| \le |G|$.
\end{proposition}

\begin{proof}
$|S| \le |\gen{S}|$ and $|\gen{S}| \cdot |S^{\perp}| = |G|$ by Corollary~\ref{cor:size}.
\end{proof}

\begin{proposition}[Upper estimate; Donoho--Stark]\label{prop:upper}
For nonempty $S \subseteq G$, $\;|G| \le |S| \cdot \big| \supp \widehat{\mathbf{1}_S} \big|$.
\end{proposition}

This is the finite uncertainty principle $|\supp f| \cdot |\supp \hat{f}| \ge |G|$, valid for all $f \ne 0$, applied to $\mathbf{1}_S$. Note also that $S^{\perp} \subseteq \supp \widehat{\mathbf{1}_S}$ always, since $\widehat{\mathbf{1}_S}(\psi) = \sum_{x \in S}\overline{\psi(x)} = |S| \ne 0$ for $\psi \in S^{\perp}$; the two propositions bound $|G|$ from below and above by $|S|$ times the size of, respectively, the smaller and the larger of two nested character sets.

\begin{theorem}[Extremality]\label{thm:extremal}
For nonempty $S \subseteq G$ the following are equivalent:
\begin{enumerate}
\item $S$ is a Poisson set;
\item $|S| \cdot |S^{\perp}| = |G|$, i.e.\ Proposition~\ref{prop:lower} is an equality;
\item $\supp\widehat{\mathbf{1}_S} = S^{\perp}$, i.e.\ the Fourier support of $\mathbf{1}_S$ is as small as possible.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) $\Rightarrow$ (2): if $S$ is a subgroup then $\gen{S} = S$ and Corollary~\ref{cor:size} gives equality. (2) $\Rightarrow$ (1): from $|S|\,|S^{\perp}| = |G| = |\gen{S}|\,|S^{\perp}|$ and $|S^{\perp}| \ge 1$, cancel to get $|S| = |\gen{S}|$, hence $S = \gen{S}$. (1) $\Rightarrow$ (3): for a subgroup $H$, orthogonality on $H$ gives $\widehat{\mathbf{1}_H}(\psi) = |H|$ for $\psi \in H^{\perp}$ and $0$ otherwise. (3) $\Rightarrow$ (2): substituting (3) into Proposition~\ref{prop:upper} gives $|G| \le |S|\,|S^{\perp}|$; combine with Proposition~\ref{prop:lower}.
\end{proof}

The uncertainty principle says a function and its transform cannot both be concentrated; Theorem~\ref{thm:extremal} identifies the sets whose indicators achieve the theoretical minimum of joint concentration, and they are precisely the subgroups.

\section{The Poisson spectrum: structure and counting}

Let $\mathcal{P}(G) = \{S \subseteq G : S \text{ nonempty Poisson set}\}$, ordered by inclusion.

\begin{theorem}[The spectrum is the subgroup lattice]\label{thm:lattice}
The map $S \mapsto \gen{S}$ is a bijection from $\mathcal{P}(G)$ to the set of subgroups of $G$, with inverse $H \mapsto H$, and it is an order isomorphism.
\end{theorem}

\begin{proof}
By Theorem A each $S \in \mathcal{P}(G)$ is a subgroup, so $\gen{S} = S$; conversely every subgroup lies in $\mathcal{P}(G)$ by Theorem~\ref{thm:classical} and contains $0$. Order preservation is then immediate. More generally, for arbitrary $S$ and $T \in \mathcal{P}(G)$ one has $S \subseteq T$ iff $\gen{S} \le \gen{T} = T$.
\end{proof}

\begin{corollary}
The number of exact Poisson summation formulas available on $G$ equals the number of subgroups of $G$.
\end{corollary}

\begin{proposition}[Lattice behaviour]\label{prop:latticebehaviour}
$\mathcal{P}(G)$ is closed under intersection, but not under union: in the Klein four-group $\Zn{2} \times \Zn{2}$, both $\{0,(1,0)\}$ and $\{0,(0,1)\}$ are Poisson sets, while $\{0,(1,0),(0,1)\}$ is not, since $(1,0)+(0,1) = (1,1)$ is absent.
\end{proposition}

Hence $\mathcal{P}(G)$ is a meet-semilattice inside the Boolean algebra of subsets of $G$, but not a sublattice: its join is the generated subgroup, strictly larger than the union in general.

\subsection{Counting on cyclic groups}

\begin{theorem}\label{thm:divisors}
For $n \ge 1$ the number of nonempty Poisson sets of $\Zn{n}$ is $d(n)$, the number of divisors of $n$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:lattice} the count is the number of subgroups of $\Zn{n}$.

\emph{Uniqueness.} A cyclic group has at most one subgroup of each order: if $|H| = m$ then $mx = 0$ for all $x \in H$, so $H \subseteq \{x : mx = 0\}$; in a cyclic group $mx = 0$ has at most $m$ solutions, so the inclusion is an equality of sets of size $m$ and $H$ is determined by $|H|$.

\emph{Existence.} Lagrange forces $|H| \mid n$; conversely for $d \mid n$ the subgroup generated by $n/d$ has order $n/\gcd(n, n/d) = d$.
\end{proof}

\begin{example}
$\Zn{12}$ supports exactly $d(12) = 6$ exact Poisson summation formulas, one for each divisor $1,2,3,4,6,12$.
\end{example}

