$\Zn{6}$ & $\emptyset,\ \{0\},\ \{0,3\},\ \{0,2,4\},\ \Zn{6}$ & $5$ \\
$\Zn{8}$ & $\emptyset,\ \{0\},\ \{0,4\},\ \{0,2,4,6\},\ \Zn{8}$ & $5$ \\
$\Zn{2} \times \Zn{2}$ & $\emptyset,\ \{0\},\ \{0,(1,0)\},\ \{0,(0,1)\},\ \{0,(1,1)\},\ G$ & $6$ \\
\bottomrule
\end{tabular}
\end{center}

Each row is a complete enumeration over all $2^{|G|}$ subsets, and in each cyclic case the number of nonempty entries is $d(n)$.

\begin{theorem}[Separation]\label{thm:separation}
$|\Zn{4}| = |\Zn{2}\times\Zn{2}| = 4$, yet the former has $4$ Poisson sets and the latter has $6$.
\end{theorem}

Consequently the size of the Poisson spectrum is not a function of $|G|$: it is a genuine isomorphism invariant. Poisson summation, in this sense, sees the isomorphism type of the group and not merely its order. Note also that $\{0,1,4\}$, the squares mod $8$, is conspicuously absent from the $\Zn{8}$ row.

\section{Application: quadratic residues}

Let $Q_n = \{a^2 : a \in \Zn{n}\}$ be the set of squares modulo $n$. These are the residue sets controlling the classical parametrisation of Pythagorean triples.

\begin{theorem}\label{thm:squares}
$Q_n$ is a Poisson set for $n = 1$ and $n = 2$, and fails to be one for $3 \le n \le 8$.
\end{theorem}

\begin{proof}
For $n = 1,2$ every residue is a square, so $Q_n = \Zn{n}$. For the failures apply Corollary~\ref{cor:dec} and exhibit a violation of closure under subtraction: $n=3$, $0-1 = 2 \notin \{0,1\}$; $n=4$, $0-1=3 \notin \{0,1\}$; $n=5$, $1-4=2 \notin \{0,1,4\}$; $n=6$, $3-4=5 \notin \{0,1,3,4\}$; $n=7$, $1-2=6 \notin \{0,1,2,4\}$; $n=8$, $1-4=5 \notin \{0,1,4\}$.
\end{proof}

\begin{proposition}
$\gen{Q_8} = \Zn{8}$, since $1 \in Q_8$ generates.
\end{proposition}

\begin{theorem}[Quantitative failure over the quadratic residues mod 8]\label{thm:gap8}
There is $y_0 \in Q_8 = \{0,1,4\}$ with $\big| D_{Q_8}(\delta_{y_0}) \big| \ge 5$.
\end{theorem}

\begin{proof}
Theorem D with $S = Q_8$, $\gen{S} = \Zn{8}$ gives the bound $|\gen{S}| - |S| = 8 - 3 = 5$. By \eqref{eq:exactdefect} the defect is in fact exactly $1 \cdot 5 = 5$ for each of the three choices of $y_0$.
\end{proof}

Since the ambient group has size $8$, an error of $5$ is not a perturbation but is of the same order as the group itself. Combined with Theorem~\ref{thm:coset}, no change of base point helps either: $Q_8$ is not even flat.

\section{Algorithms}

The classification converts an analytic quantifier over $\mathbb{C}^{G}$ into finite combinatorics.

\medskip\noindent\textbf{Algorithm 1 (Poisson set test).} Given $S \subseteq G$: return true if $S = \emptyset$; otherwise return $(0 \in S) \wedge (\forall x,y \in S: x-y \in S)$. Cost $O(|S|^2)$ group operations with $O(1)$ membership tests. Correctness: Corollary~\ref{cor:dec}. The naive approach --- verifying \eqref{eq:PS} for a spanning set of $|G|$ test functions with $|G|$-term Fourier sums --- costs $O(|G|^3)$ complex operations, or $O(|G|^2 \log |G|)$ with fast transforms.

\medskip\noindent\textbf{Algorithm 2 (Generated subgroup by closure).} Initialise $C = \{0\} \cup S$ and repeatedly replace $C$ by $C \cup (C - C)$ until stable. Terminates in at most $\log_2 |G|$ rounds; cost $O(|G|^2)$ worst case.

\medskip\noindent\textbf{Algorithm 3 (Exact defect evaluation).} Compute $D_S(f)$ (a) directly from the definition by enumerating characters, in $O(|G|^2)$; and (b) via Theorem C as $\tfrac{|G|}{|\gen{S}|}\big(|\gen{S}| \sum_S f - |S| \sum_{\gen{S}} f\big)$, in $O(|G|)$ without touching a character. Their agreement is a numerical certificate of the defect formula.

\medskip\noindent\textbf{Algorithm 4 (Spectrum enumeration).} Iterate over all $2^{|G|}$ subsets applying Algorithm 1, or --- exponentially faster --- enumerate subgroups as $\gen{T}$ over small generating sets $T$ and deduplicate. For cyclic $\Zn{n}$ the spectrum is $\{\gen{n/d} : d \mid n\} \cup \{\emptyset\}$, of size $d(n)+1$.

\section{Discussion and future directions}

\subsection{What the converse changes}

\emph{Logical.} A statement quantified over an apparently infinite-dimensional space of test functions is equivalent to a finite check on $S$, and by Theorem B to a single evaluation.

\emph{Structural.} The family of Poisson formulas on $G$ is a copy of the subgroup lattice, meet-closed and join-incomplete, and its cardinality distinguishes non-isomorphic groups of equal order.

\emph{Quantitative.} By \eqref{eq:exactdefect} the defect at a delta is a positive integer, factoring as index times deficiency. There is no continuum of near-Poisson sets around which to build a perturbation theory.

\subsection{Future directions}

\begin{conjecture}[Approximate Poisson sets in the $\ell^1$-averaged sense]
For nonempty $S \subseteq G$ define $D(S) = \sup_{\|f\|_{\infty} \le 1} |D_S(f)| / |G|$. Then $D(S) = 2\big(1 - |S|/|\gen{S}|\big)\cdot\big(\text{something explicitly computable from } (S, \gen{S})\big)$, and in particular $D(S) \ge 1/|\gen{S}|$ with equality iff $S$ is a subgroup minus one point.
\end{conjecture}

The key insight is that the defect formula already expresses the defect as $|G|\big(|\gen{S}|\sum_S f - |S| \sum_{\gen{S}} f\big)/|\gen{S}|$, i.e.\ as a signed measure supported on $\gen{S}$ with mass $|S|$ on $S$; the supremum over $\|f\|_\infty \le 1$ is therefore the total variation of that measure, a purely combinatorial quantity. Falsifiable by computing $D(S)$ for all $S \subseteq \Zn{8}$ by exhaustion.

\begin{conjecture}[Poisson spectrum determines the group]
For finite abelian $G$, $H$, the multiset $\{|S| : S$ a nonempty Poisson set of $G\}$ determines $G$ up to isomorphism.
\end{conjecture}

By Theorem~\ref{thm:lattice} this multiset is exactly the multiset of subgroup orders, so the conjecture asserts that a finite abelian group is determined by its subgroup-order multiset --- false in general for arbitrary groups, but plausible for abelian ones ($\Zn{4}$ gives $\{1,2,4\}$, the Klein group $\{1,2,2,2,4\}$). The analytic side is entirely eliminated; what remains can be attacked through the structure theorem, and refuted or confirmed by exhaustion for abelian groups of order $\le 64$. Falsifiable by searching for two non-isomorphic abelian groups with equal subgroup-order multisets, e.g.\ of order $p^4$ or $p^5$.

\begin{conjecture}[Weighted / non-flat Poisson sets]
Let $w : G \to \mathbb{C}$ be supported on a nonempty $S$ and suppose that for all $f$,
\[
|G| \sum_{x} w(x) f(x) \;=\; c \sum_{\psi \in \supp(\hat w)} \hat w(\psi)\, \hat f(\psi)
\]
for some constant $c$. Then $w$ is a scalar multiple of a coset indicator times a character.
\end{conjecture}

This would unify Theorem A and Theorem~\ref{thm:coset} into a single weighted statement, the character factor accounting for the translation phase of Lemma~\ref{lem:phase}.

\subsection{Further questions}

\begin{itemize}
\item \textbf{Non-abelian analogues.} Replacing characters by irreducible representations and $S^{\perp}$ by the representations trivial on $S$, does Theorem A survive with ``subgroup'' replaced by ``normal subgroup''? Lemma~\ref{lem:blind} survives verbatim, since the kernel of a representation is normal, which suggests the right statement involves the normal closure.
\item \textbf{Locally compact groups.} For a closed subgroup of a locally compact abelian group, Poisson summation holds with Haar measures; what is the analogue of Theorem B when the Dirac delta is replaced by an approximate identity?
\item \textbf{Stability in weaker norms.} Corollary~\ref{cor:gap} rules out approximate Poisson sets for the $\ell^\infty$ test class. What is the correct statement for defect measured against random $f$, or against nonnegative $f$?
\item \textbf{Algorithmic group recovery.} Theorem B gives a one-query subgroup test for a set accessible only through the oracle $f \mapsto \sum_{x \in S} f(x)$. What is the query complexity of \emph{recovering} $\gen{S}$, or of estimating $|\gen{S}| - |S|$, from such an oracle?
\end{itemize}

\section{Summary of results}

\begin{enumerate}
\item \textbf{Blindness lemma.} $S^{\perp} = \gen{S}^{\perp}$ for every $S$, hence $|\gen{S}|\,|S^{\perp}| = |G|$.
\item \textbf{Fundamental character sum.} $|\gen{S}| \sum_{\psi \in S^{\perp}} \overline{\psi(y)} = |G| \cdot \mathbf{1}[y \in \gen{S}]$.
\item \textbf{One-test-function rigidity.} A single Dirac delta at a point of $S$ forces $S = \gen{S}$.
\item \textbf{Classification.} $S$ is Poisson iff $S = \emptyset$ or $S$ is a subgroup; equivalently, for nonempty $S$, iff $0 \in S$ and $S$ is closed under subtraction.
\item \textbf{Exact defect formula.} $|\gen{S}| D_S(f) = |G|\big(|\gen{S}|\sum_S f - |S| \sum_{\gen{S}} f\big)$.
\item \textbf{Gap theorem.} For nonempty non-subgroups the defect at a delta is exactly $[G:\gen{S}](|\gen{S}| - |S|) \ge 1$.
\item \textbf{Constant rigidity.} No renormalisation rescues a non-subgroup; the constant $|S|$ is forced.
\item \textbf{Coset characterisation.} The phase-twisted affine identity holds iff $S$ is a coset.
\item \textbf{Uncertainty extremality.} Poisson $\iff |S|\,|S^{\perp}| = |G| \iff \supp\widehat{\mathbf{1}_S} = S^{\perp}$.
\item \textbf{Spectrum.} Nonempty Poisson sets form a copy of the subgroup lattice: meet-closed, not join-closed; of size $d(n)$ on $\Zn{n}$; distinguishing $\Zn{4}$ from the Klein four-group.
\item \textbf{Quadratic residues.} Squares mod $n$ are Poisson only for $n \in \{1,2\}$; mod $8$ they fail with defect exactly $5$ and are not even a coset.
\end{enumerate}

\end{document}

