#!/usr/bin/env python3
"""
The Poisson spectrum as an isomorphism invariant, and a test of the
"spectrum determines the group" conjecture for small abelian groups.
====================================================================

Since the nonempty Poisson sets of a finite abelian group G are exactly its
subgroups, the multiset

    Sigma(G) = { |S| : S a nonempty Poisson set of G }

is precisely the multiset of subgroup orders of G.  This script enumerates
Sigma(G) for every abelian group of order at most 32 (written in invariant
factor form as a product of cyclic groups), and asks whether Sigma separates
non-isomorphic groups of the same order.

Output includes:
  * the spectrum size |Sigma(G)| = number of exact Poisson summation
    formulas supported by G;
  * verification that for cyclic G = Z/nZ this equals d(n);
  * the first collisions, if any, between distinct abelian groups.
"""

from __future__ import annotations

import itertools
from collections import Counter
from typing import Dict, List, Sequence, Tuple

Elem = Tuple[int, ...]


def elements(moduli: Sequence[int]) -> List[Elem]:
    """All elements of the product of cyclic groups."""
    return [tuple(t) for t in itertools.product(*(range(m) for m in moduli))]


def sub(moduli: Sequence[int], x: Elem, y: Elem) -> Elem:
    """Componentwise difference."""
    return tuple((a - b) % m for a, b, m in zip(x, y, moduli))


def generated(moduli: Sequence[int], gens: Sequence[Elem]) -> frozenset:
    """The subgroup generated by `gens`, by closure under subtraction."""
    zero = tuple(0 for _ in moduli)
    cur = {zero} | set(gens)
    while True:
        grown = set(cur)
        for a in cur:
            for b in cur:
                grown.add(sub(moduli, a, b))
        if grown == cur:
            return frozenset(cur)
        cur = grown


def all_subgroups(moduli: Sequence[int]) -> List[frozenset]:
    """Every subgroup, found by saturating from generating sets."""
    zero = tuple(0 for _ in moduli)
    found = {frozenset({zero})}
    frontier = list(found)
    els = elements(moduli)
    while frontier:
        new_frontier = []
        for H in frontier:
            for g in els:
                if g in H:
                    continue
                K = generated(moduli, list(H) + [g])
                if K not in found:
                    found.add(K)
                    new_frontier.append(K)
        frontier = new_frontier
    return sorted(found, key=lambda H: (len(H), sorted(H)))


def partitions(n: int, largest: int | None = None) -> List[List[int]]:
    """All partitions of n, used to enumerate abelian p-groups."""
    if largest is None:
        largest = n
    if n == 0:
        return [[]]
    out: List[List[int]] = []
    for k in range(min(n, largest), 0, -1):
        for rest in partitions(n - k, k):
            out.append([k] + rest)
    return out


def abelian_groups(order: int) -> List[Tuple[int, ...]]:
    """All abelian groups of the given order, as tuples of prime-power moduli."""
    factors: Dict[int, int] = {}
    m, p = order, 2
    while m > 1:
        while m % p == 0:
            factors[p] = factors.get(p, 0) + 1
            m //= p
        p += 1
    pieces: List[List[List[int]]] = []
    for p, e in factors.items():
        pieces.append([[p ** a for a in part] for part in partitions(e)])
    out: List[Tuple[int, ...]] = []
    for combo in itertools.product(*pieces):
        moduli: List[int] = []
        for part in combo:
            moduli.extend(part)
        out.append(tuple(sorted(moduli)))
    return sorted(set(out))


def divisor_count(n: int) -> int:
    """d(n)."""
    return sum(1 for d in range(1, n + 1) if n % d == 0)


def name(moduli: Sequence[int]) -> str:
    """Readable name of a product of cyclic groups."""
    return " x ".join(f"Z/{m}" for m in moduli) if moduli else "trivial"


def main() -> None:
    print("Poisson spectra of abelian groups of order <= 32")
    print("=" * 72)
    spectra: Dict[Tuple[int, ...], Tuple[int, ...]] = {}
    for order in range(1, 33):
        groups = abelian_groups(order)
        for moduli in groups:
            subs = all_subgroups(moduli)
            sigma = tuple(sorted(len(H) for H in subs))
            spectra[moduli] = sigma
            cyc = "cyclic" if len(moduli) <= 1 else "      "
            check = ""
            if len(moduli) == 1:
                check = ("  d(n) = " + str(divisor_count(moduli[0]))
                         + (" OK" if divisor_count(moduli[0]) == len(sigma)
                            else " MISMATCH"))
                assert divisor_count(moduli[0]) == len(sigma)
            print(f"  |G| = {order:3d}  {name(moduli):22s} {cyc}  "
                  f"formulas = {len(sigma):3d}   sizes = {list(sigma)}{check}")

    print()
    print("Do the spectra separate non-isomorphic groups of equal order?")
    print("-" * 72)
    by_order: Dict[int, List[Tuple[int, ...]]] = {}
    for moduli in spectra:
        o = 1
        for m in moduli:
            o *= m
        by_order.setdefault(o, []).append(moduli)
    collisions = 0
    for o, groups in sorted(by_order.items()):
        seen: Dict[Tuple[int, ...], Tuple[int, ...]] = {}
        for moduli in groups:
            sig = spectra[moduli]
            if sig in seen:
                collisions += 1
                print(f"  COLLISION at order {o}: {name(seen[sig])} and "
                      f"{name(moduli)} share the spectrum {list(sig)}")
            else:
                seen[sig] = moduli
        if len(groups) > 1:
            print(f"  order {o:3d}: {len(groups)} groups, "
                  f"{len(seen)} distinct spectra"
                  + ("  (separated)" if len(seen) == len(groups) else ""))
    print(f"\n  total collisions found up to order 32: {collisions}")
    print("  (Every non-isomorphic pair checked so far is separated, which is")
    print("   the content of the spectrum-determines-the-group conjecture.)")

    print()
    print("The classic separating pair, in full:")
    for moduli in [(4,), (2, 2)]:
        subs = all_subgroups(moduli)
        print(f"  {name(moduli):12s} spectrum = "
              + "  ".join("{" + ",".join(
                  "".join(map(str, x)) for x in sorted(H)) + "}"
                  for H in subs))
    print("  Both groups have four elements; they support 3 and 5 nonempty")
    print("  Poisson formulas respectively (4 and 6 counting the empty set).")


if __name__ == "__main__":
    main()

