"""Algorithm 2 — Iterated difference closure for the generated subgroup.

Computes <S>, the smallest subgroup containing S, by repeatedly saturating
under subtraction.  Each non-terminal round at least doubles the current set,
so at most log_2 |G| rounds occur; total cost O(|G|^2) in the worst case.
"""

from typing import FrozenSet, Iterable, Sequence, Set, Tuple

Elem = Tuple[int, ...]


def generated_subgroup(moduli: Sequence[int],
                       S: Iterable[Elem]) -> FrozenSet[Elem]:
    """The subgroup <S> of Z/m_1 x ... x Z/m_r generated by S."""
    zero: Elem = tuple(0 for _ in moduli)
    current: Set[Elem] = {zero} | set(S)
    while True:
        grown: Set[Elem] = set(current)
        for a in current:
            for b in current:
                grown.add(tuple((p - q) % m
                                for p, q, m in zip(a, b, moduli)))
        if len(grown) == len(current):
            return frozenset(current)
        current = grown


def deficiency(moduli: Sequence[int], S: Iterable[Elem]) -> int:
    """|<S>| - |S|: the number of points S is missing from the subgroup it
    generates.  Zero exactly for subgroups; at least 1 otherwise."""
    Sset = set(S)
    return len(generated_subgroup(moduli, Sset)) - len(Sset)
